mapper.select:
SELECT


    ,u.nick_name,u.avatar

FROM video_info v

    LEFT JOIN user_info u ON v.user_id = u.user_id



    ORDER BY ${query.orderBy}


    LIMIT #{query.simplePage.start}, #{query.simplePage.pageSize}

mapper.update:
UPDATE video_info
video_name = #{videoInfo.videoName}, video_cover = #{videoInfo.videoCover}, introduction = #{videoInfo.introduction}, duration = #{videoInfo.duration}, tags = #{videoInfo.tags}, p_category_id = #{videoInfo.pCategoryId}, category_id = #{videoInfo.categoryId}, post_type = #{videoInfo.postType}, origin_info = #{videoInfo.originInfo}, interaction = #{videoInfo.interaction}, last_play_time = #{videoInfo.lastPlayTime}, recommend_type = #{videoInfo.recommendType}, play_count = #{videoInfo.playCount}, like_count = #{videoInfo.likeCount}, coin_count = #{videoInfo.coinCount}, collect_count = #{videoInfo.collectCount}, comment_count = #{videoInfo.commentCount}, danmu_count = #{videoInfo.danmuCount}, last_update_time = #{videoInfo.lastUpdateTime},
AND video_id = #{query.videoId}
AND user_id = #{query.userId}
AND status = #{query.status}
